effect.shader:
void main(){
  vec2 uv = acScreenNorm;
  vec2 p = (uv - 0.5) * 2.0;
  float w = 1.0 + tiltX * p.x * mixAmt + tiltY * p.y * mixAmt;
  p /= max(w, 0.1);
  p /= max(zoom, 0.05);
  vec2 tuv = p * 0.5 + 0.5;
  vec4 warped = texture2DCv(inputImg.texture, tuv);
  vec4 orig = texture2DCv(inputImg.texture, uv);
  float inside = step(0.0, tuv.x) * step(tuv.x, 1.0) * step(0.0, tuv.y) * step(tuv.y, 1.0);
  gl_FragColor = mix(orig, warped * inside, mixAmt);
}
